// Üç giriş de buradan geçer:
//  • POST webhook'ta alanlar "body" içinde,
//  • GET webhook'ta "query" içinde,
//  • workflow 05'in /arac komutunda doğrudan gelir.
const j = $input.first().json || {};
const webhooktan = Object.prototype.hasOwnProperty.call(j, 'body') || Object.prototype.hasOwnProperty.call(j, 'query');
const govde = Object.keys(j.body || {}).length ? j.body : (Object.keys(j.query || {}).length ? j.query : j);

let islem = String(govde.islem || govde.komut || '').trim().toLowerCase();
let veri = govde.veri !== undefined ? String(govde.veri) : String(govde.metin || '');

// Telegram tek metin yollar: "/arac jwt eyJ..." → islem = jwt, veri = eyJ...
if (!islem && veri) {
  const ilk = veri.trim().split(/\s+/)[0].toLowerCase();
  islem = ilk;
  veri = veri.trim().slice(ilk.length).trim();
}

return [{ json: {
  islem: islem.replace(/^\//, ''),
  veri,
  chat_id: govde.chat_id ? String(govde.chat_id) : '',
  webhooktan,
} }];

// Geliştirici araç kutusu — hepsi saf JavaScript, dış bağımlılık yok.
const istek = $input.first().json || {};
const islem = String(istek.islem || '').toLowerCase();
const veri = String(istek.veri || '');
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));

// ── UTF-8 ve base64 (Buffer/atob'a güvenmeden) ───────────────────────────────
const ALFABE = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const baytlar = (s) => {
  const out = [];
  for (const ch of String(s)) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) out.push(cp);
    else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 63));
    else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
    else out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
  }
  return out;
};
const metne = (b) => {
  let s = '';
  for (let i = 0; i < b.length;) {
    const c = b[i++];
    if (c < 0x80) s += String.fromCodePoint(c);
    else if (c < 0xe0) s += String.fromCodePoint(((c & 31) << 6) | (b[i++] & 63));
    else if (c < 0xf0) s += String.fromCodePoint(((c & 15) << 12) | ((b[i++] & 63) << 6) | (b[i++] & 63));
    else s += String.fromCodePoint(((c & 7) << 18) | ((b[i++] & 63) << 12) | ((b[i++] & 63) << 6) | (b[i++] & 63));
  }
  return s;
};
const b64Kodla = (s) => {
  const b = baytlar(s);
  let out = '';
  for (let i = 0; i < b.length; i += 3) {
    const n = (b[i] << 16) | ((b[i + 1] || 0) << 8) | (b[i + 2] || 0);
    out += ALFABE[(n >> 18) & 63] + ALFABE[(n >> 12) & 63] +
      (i + 1 < b.length ? ALFABE[(n >> 6) & 63] : '=') +
      (i + 2 < b.length ? ALFABE[n & 63] : '=');
  }
  return out;
};
const b64Coz = (s) => {
  const t = String(s).replace(/-/g, '+').replace(/_/g, '/').replace(/[^A-Za-z0-9+/]/g, '');
  const b = [];
  for (let i = 0; i < t.length; i += 4) {
    const n = (ALFABE.indexOf(t[i]) << 18) | (ALFABE.indexOf(t[i + 1]) << 12) |
      ((ALFABE.indexOf(t[i + 2]) & 63) << 6) | (ALFABE.indexOf(t[i + 3]) & 63);
    b.push((n >> 16) & 255);
    if (t[i + 2] !== undefined) b.push((n >> 8) & 255);
    if (t[i + 3] !== undefined) b.push(n & 255);
  }
  return metne(b);
};

// ── SHA-256 (RFC 6234) ──────────────────────────────────────────────────────
const sha256 = (mesaj) => {
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2];
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const b = baytlar(mesaj);
  const bitUzunluk = b.length * 8;
  b.push(0x80);
  while (b.length % 64 !== 56) b.push(0);
  for (let i = 7; i >= 0; i--) b.push(Math.floor(bitUzunluk / Math.pow(2, i * 8)) & 255);

  const don = (x, n) => (x >>> n) | (x << (32 - n));
  const w = new Array(64);
  for (let i = 0; i < b.length; i += 64) {
    for (let t = 0; t < 16; t++) {
      w[t] = (b[i + t * 4] << 24) | (b[i + t * 4 + 1] << 16) | (b[i + t * 4 + 2] << 8) | b[i + t * 4 + 3];
    }
    for (let t = 16; t < 64; t++) {
      const s0 = don(w[t - 15], 7) ^ don(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      const s1 = don(w[t - 2], 17) ^ don(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) | 0;
    }
    let [a, bb, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = don(e, 6) ^ don(e, 11) ^ don(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[t] + w[t]) | 0;
      const S0 = don(a, 2) ^ don(a, 13) ^ don(a, 22);
      const maj = (a & bb) ^ (a & c) ^ (bb & c);
      const t2 = (S0 + maj) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0;
      d = c; c = bb; bb = a; a = (t1 + t2) | 0;
    }
    const yeni = [a, bb, c, d, e, f, g, h];
    for (let t = 0; t < 8; t++) H[t] = (H[t] + yeni[t]) | 0;
  }
  return H.map((x) => (x >>> 0).toString(16).padStart(8, '0')).join('');
};

// ── Rastgelelik ─────────────────────────────────────────────────────────────
const rastgeleBaytlar = (n) => {
  try {
    if (typeof globalThis !== 'undefined' && globalThis.crypto && globalThis.crypto.getRandomValues) {
      const a = new Uint8Array(n);
      globalThis.crypto.getRandomValues(a);
      return { bayt: Array.from(a), guclu: true };
    }
  } catch (e) { /* sandbox izin vermiyorsa Math.random'a düşülür */ }
  return { bayt: Array.from({ length: n }, () => Math.floor(Math.random() * 256)), guclu: false };
};

const trSaat = (d) => d.toLocaleString('tr-TR', { dateStyle: 'medium', timeStyle: 'short' });
const gorece = (ms) => {
  const fark = Math.round((ms - Date.now()) / 1000);
  const mutlak = Math.abs(fark);
  const birim = mutlak < 60 ? [mutlak, 'saniye'] : mutlak < 3600 ? [Math.round(mutlak / 60), 'dakika']
    : mutlak < 86400 ? [Math.round(mutlak / 3600), 'saat'] : [Math.round(mutlak / 86400), 'gün'];
  return fark >= 0 ? birim[0] + ' ' + birim[1] + ' sonra' : birim[0] + ' ' + birim[1] + ' önce';
};

// ── cron ────────────────────────────────────────────────────────────────────
const GUN_ADI = ['Pazar', 'Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi'];
const AY_ADI = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık'];
const alanCoz = (ifade, enAz, enCok, ad) => {
  const kume = new Set();
  for (const parca of String(ifade).split(',')) {
    const m = parca.match(/^(\*|\d+)(?:-(\d+))?(?:\/(\d+))?$/);
    if (!m) throw new Error(ad + ' alanı anlaşılamadı: "' + parca + '"');
    const adim = m[3] ? Number(m[3]) : 1;
    if (adim < 1) throw new Error(ad + ' alanında adım 0 olamaz.');
    let bas = m[1] === '*' ? enAz : Number(m[1]);
    let son = m[1] === '*' ? enCok : (m[2] !== undefined ? Number(m[2]) : (m[3] ? enCok : Number(m[1])));
    if (bas < enAz || son > enCok || bas > son) throw new Error(ad + ' alanı ' + enAz + '-' + enCok + ' aralığında olmalı.');
    for (let v = bas; v <= son; v += adim) kume.add(v);
  }
  return kume;
};
const alanAnlat = (ifade, tekil, cogul, bicim) => {
  if (ifade === '*') return '';
  const m = String(ifade).match(/^\*\/(\d+)$/);
  if (m) return 'her ' + m[1] + ' ' + cogul + 'de bir';
  const araM = String(ifade).match(/^(\d+)-(\d+)$/);
  if (araM) {
    const ad = (n) => (bicim ? bicim(Number(n)) : n);
    return ad(araM[1]) + '-' + ad(araM[2]) + ' ' + tekil + ' arası';
  }
  return String(ifade).split(',').map((x) => (bicim ? bicim(Number(x)) : x)).join(', ') + ' ' + tekil;
};

let sonuc = '';
let basarili = true;

try {
  if (islem === 'uuid') {
    const { bayt, guclu } = rastgeleBaytlar(16);
    bayt[6] = (bayt[6] & 0x0f) | 0x40;
    bayt[8] = (bayt[8] & 0x3f) | 0x80;
    const h = bayt.map((x) => x.toString(16).padStart(2, '0')).join('');
    const uuid = [h.slice(0, 8), h.slice(8, 12), h.slice(12, 16), h.slice(16, 20), h.slice(20)].join('-');
    sonuc = uuid + '\n\nKısa kimlik: ' + h.slice(0, 12) +
      (guclu ? '' : '\n(Math.random ile üretildi — sır olarak kullanmayın.)');
  } else if (islem === 'b64' || islem === 'base64') {
    if (!veri) throw new Error('Kullanım: b64 <metin>');
    const b64Gibi = /^[A-Za-z0-9+/_-]+={0,2}$/.test(veri.replace(/\s+/g, '')) && veri.replace(/\s+/g, '').length % 4 === 0;
    if (b64Gibi) {
      const cozulen = b64Coz(veri);
      sonuc = /[\x00-\x08\x0e-\x1f]/.test(cozulen)
        ? 'Çözülen veri metin değil (ikili). Kodlanmış hâli:\n' + b64Kodla(veri)
        : 'Çözüldü:\n' + cozulen;
    } else {
      sonuc = 'Kodlandı:\n' + b64Kodla(veri);
    }
  } else if (islem === 'b64kodla') {
    if (!veri) throw new Error('Kullanım: b64kodla <metin>');
    sonuc = b64Kodla(veri);
  } else if (islem === 'b64coz' || islem === 'b64çöz') {
    if (!veri) throw new Error('Kullanım: b64coz <base64>');
    sonuc = b64Coz(veri);
  } else if (islem === 'jwt') {
    const parcalar = veri.trim().split('.');
    if (parcalar.length < 2) throw new Error('Bu bir JWT değil (nokta ile ayrılmış en az 2 parça bekleniyor).');
    const basSatir = JSON.parse(b64Coz(parcalar[0]));
    const govde = JSON.parse(b64Coz(parcalar[1]));
    const satirlar = ['Başlık:', JSON.stringify(basSatir, null, 2), '', 'Gövde:', JSON.stringify(govde, null, 2)];
    const zamanAlan = (ad, etiket) => {
      if (typeof govde[ad] !== 'number') return;
      const d = new Date(govde[ad] * 1000);
      satirlar.push(etiket + ': ' + trSaat(d) + ' (' + gorece(d.getTime()) + ')');
    };
    satirlar.push('');
    zamanAlan('iat', 'Üretilme (iat)');
    zamanAlan('nbf', 'Geçerlilik başlangıcı (nbf)');
    zamanAlan('exp', 'Bitiş (exp)');
    if (typeof govde.exp === 'number') {
      satirlar.push(govde.exp * 1000 < Date.now() ? '⛔ Süresi GEÇMİŞ' : '✅ Hâlâ geçerli');
    }
    satirlar.push('', 'Not: imza doğrulanmadı (yerel araç, anahtar yok).');
    sonuc = satirlar.join('\n');
  } else if (islem === 'zaman' || islem === 'time') {
    let d;
    if (!veri) d = new Date();
    else if (/^\d{13}$/.test(veri.trim())) d = new Date(Number(veri.trim()));
    else if (/^\d{10}$/.test(veri.trim())) d = new Date(Number(veri.trim()) * 1000);
    else d = new Date(veri.trim());
    if (isNaN(d.getTime())) throw new Error('Zaman anlaşılamadı. Örnek: 1735689600 · 2026-01-01T00:00:00Z · "zaman" (şimdi)');
    sonuc = [
      'ISO 8601 : ' + d.toISOString(),
      'Yerel     : ' + trSaat(d),
      'epoch (s) : ' + Math.floor(d.getTime() / 1000),
      'epoch (ms): ' + d.getTime(),
      'Gün       : ' + GUN_ADI[d.getDay()],
      'Görece    : ' + gorece(d.getTime()),
    ].join('\n');
  } else if (islem === 'json') {
    if (!veri) throw new Error('Kullanım: json {"a":1}');
    let ayrisan;
    try {
      ayrisan = JSON.parse(veri);
    } catch (e) {
      const konum = Number((String(e.message).match(/position (\d+)/) || [])[1]);
      let yer = '';
      if (Number.isFinite(konum)) {
        const oncesi = veri.slice(0, konum);
        const satir = oncesi.split('\n').length;
        const sutun = konum - oncesi.lastIndexOf('\n');
        yer = '\nSatır ' + satir + ', sütun ' + sutun + ':\n' + veri.slice(Math.max(0, konum - 30), konum + 30);
      }
      throw new Error('Geçersiz JSON: ' + e.message + yer);
    }
    const derinlik = (x) => (x && typeof x === 'object')
      ? 1 + Math.max(0, ...Object.values(x).map(derinlik)) : 0;
    const sayac = Array.isArray(ayrisan) ? ayrisan.length + ' öğe'
      : (ayrisan && typeof ayrisan === 'object') ? Object.keys(ayrisan).length + ' anahtar' : 'tek değer';
    sonuc = '✅ Geçerli JSON — ' + sayac + ', derinlik ' + derinlik(ayrisan) + '\n\n' + JSON.stringify(ayrisan, null, 2);
  } else if (islem === 'sha256' || islem === 'sha') {
    if (!veri) throw new Error('Kullanım: sha256 <metin>');
    sonuc = sha256(veri);
  } else if (islem === 'parola' || islem === 'sifre' || islem === 'şifre') {
    const uzunluk = Math.min(128, Math.max(8, Number(veri) || 20));
    const havuz = 'abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789!@#%^&*-_=+?';
    const { bayt, guclu } = rastgeleBaytlar(uzunluk);
    sonuc = bayt.map((b) => havuz[b % havuz.length]).join('') +
      (guclu ? '\n(crypto.getRandomValues ile üretildi)' : '\n(Math.random ile üretildi — kritik sırlar için: openssl rand -base64 24)');
  } else if (islem === 'url') {
    if (!veri) throw new Error('Kullanım: url <metin>');
    sonuc = veri.includes('%')
      ? 'Çözüldü:\n' + decodeURIComponent(veri) + '\n\nKodlanmış hâli:\n' + encodeURIComponent(veri)
      : 'Kodlandı:\n' + encodeURIComponent(veri);
  } else if (islem === 'cron') {
    const alanlar = veri.trim().split(/\s+/);
    if (alanlar.length !== 5) throw new Error('5 alan bekleniyor: dakika saat ayın-günü ay haftanın-günü\nÖrnek: 0 */4 * * *');
    const [dk, sa, ayGun, ay, haftaGun] = alanlar;
    const dkK = alanCoz(dk, 0, 59, 'Dakika');
    const saK = alanCoz(sa, 0, 23, 'Saat');
    const ayGunK = alanCoz(ayGun, 1, 31, 'Ayın günü');
    const ayK = alanCoz(ay, 1, 12, 'Ay');
    const haftaK = new Set([...alanCoz(haftaGun, 0, 7, 'Haftanın günü')].map((x) => x % 7));

    const dkAdim = dk.match(/^\*\/(\d+)$/);
    const saAdim = sa.match(/^\*\/(\d+)$/);
    const zamanMetni = (() => {
      if (dk === '*' && sa === '*') return 'her dakika';
      if (sa === '*' && dkAdim) return 'her ' + dkAdim[1] + ' dakikada bir';
      if (sa === '*' && /^\d+$/.test(dk)) return 'her saat ' + dk + '. dakikada';
      if (/^\d+$/.test(dk) && /^\d+$/.test(sa)) {
        const saat = sa.padStart(2, '0') + ':' + dk.padStart(2, '0');
        return (ayGun === '*' && haftaGun === '*' && ay === '*') ? 'her gün saat ' + saat : 'saat ' + saat;
      }
      if (/^\d+$/.test(dk) && saAdim) return 'her ' + saAdim[1] + ' saatte bir, ' + dk + '. dakikada';
      return [alanAnlat(sa, 'saatte', 'saat'), alanAnlat(dk, 'dakikada', 'dakika')]
        .filter(Boolean).join(', ') || 'belirtilen zamanda';
    })();
    const parcalar = [zamanMetni];
    if (ayGun !== '*') parcalar.push('ayın ' + alanAnlat(ayGun, 'günü', 'gün', (n) => n + '.'));
    if (ay !== '*') parcalar.push(alanAnlat(ay, 'ayında', 'ay', (n) => AY_ADI[n - 1] || n));
    if (haftaGun !== '*') parcalar.push(alanAnlat(haftaGun, 'günleri', 'gün', (n) => GUN_ADI[n % 7] || n));

    const gunEsler = (d) => {
      const gunTamam = ayGunK.has(d.getDate());
      const haftaTamam = haftaK.has(d.getDay());
      if (ayGun === '*' && haftaGun === '*') return true;
      if (ayGun === '*') return haftaTamam;
      if (haftaGun === '*') return gunTamam;
      return gunTamam || haftaTamam; // cron'da ikisi de doluysa VEYA geçerlidir
    };

    const sonraki = [];
    const d = new Date();
    d.setSeconds(0, 0);
    d.setMinutes(d.getMinutes() + 1);
    for (let i = 0; i < 366 * 24 * 60 && sonraki.length < 3; i++) {
      if (dkK.has(d.getMinutes()) && saK.has(d.getHours()) && ayK.has(d.getMonth() + 1) && gunEsler(d)) {
        sonraki.push(trSaat(new Date(d)));
      }
      d.setMinutes(d.getMinutes() + 1);
    }
    sonuc = '⏱ ' + veri.trim() + '\n→ ' + parcalar.join(', ') + '\n\nSonraki çalışmalar:\n' +
      (sonraki.length ? sonraki.map((x) => '• ' + x).join('\n') : '• bir yıl içinde çalışmıyor');
  } else if (islem === 'slug') {
    if (!veri) throw new Error('Kullanım: slug <başlık>');
    const harita = { ç: 'c', ğ: 'g', ı: 'i', ö: 'o', ş: 's', ü: 'u', Ç: 'c', Ğ: 'g', İ: 'i', Ö: 'o', Ş: 's', Ü: 'u', I: 'i' };
    sonuc = veri
      .split('')
      .map((c) => harita[c] !== undefined ? harita[c] : c)
      .join('')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 100) || '(boş)';
  } else if (islem === 'hex') {
    const t = veri.trim();
    if (!t) throw new Error('Kullanım: hex 255 · hex 0xff');
    let n;
    if (/^0x[0-9a-f]+$/i.test(t)) n = parseInt(t.slice(2), 16);
    else if (/^[0-9]+$/.test(t)) n = Number(t);
    else if (/^[0-9a-f]+$/i.test(t)) n = parseInt(t, 16);
    else throw new Error('Sayı anlaşılamadı: ' + t);
    if (!Number.isFinite(n)) throw new Error('Sayı çok büyük.');
    sonuc = ['Onluk   : ' + n, 'Onaltılık: 0x' + n.toString(16), 'İkilik  : 0b' + n.toString(2),
      'Sekizlik: 0o' + n.toString(8), 'Bayt    : ' + (n / 1024 >= 1 ? (n / 1024).toFixed(1) + ' KB' : n + ' B')].join('\n');
  } else {
    basarili = false;
    sonuc = [
      '🧰 Araç kutusu — kullanılabilir işlemler:',
      '',
      'uuid                 → UUID v4',
      'b64 <metin>          → base64 kodla/çöz',
      'jwt <token>          → JWT içeriğini aç',
      'zaman [değer]        → epoch ↔ ISO ↔ yerel saat',
      'json <metin>         → doğrula + biçimlendir',
      'sha256 <metin>       → SHA-256 özeti',
      'parola [uzunluk]     → rastgele parola',
      'url <metin>          → yüzde kodlaması',
      'cron <ifade>         → Türkçe açıklama + sonraki 3 çalışma',
      'slug <başlık>        → URL uyumlu ad',
      'hex <sayı>           → onluk ↔ onaltılık ↔ ikilik',
      '',
      islem ? 'Bilinmeyen işlem: ' + islem : 'Örnek: /arac cron 0 */4 * * *',
    ].join('\n');
  }
} catch (e) {
  basarili = false;
  sonuc = '⚠️ ' + e.message;
}

const kirp = (s, n) => (s.length > n ? s.slice(0, n) + '\n… (kırpıldı)' : s);
return [{ json: {
  islem: islem || 'yardim',
  basarili,
  sonuc: kirp(sonuc, 12000),
  telegramText: '<pre>' + esc(kirp(sonuc, 3500)) + '</pre>',
  chat_id: istek.chat_id,
  webhooktan: istek.webhooktan,
} }];

// Yanıt düğümü yalnızca webhook ile gelen isteklerde çalışmalı;
// workflow 05'ten gelen çağrıda yanıtlanacak bir HTTP isteği yoktur.
const j = $input.first().json;
return j.webhooktan ? [{ json: j }] : [];

// İstek Telegram'dan geldiyse sonuç oraya gider (kod bloğu olarak).
const j = $input.first().json;
if (!j.chat_id) return [];
return [{ json: { chat_id: j.chat_id, text: String(j.telegramText).slice(0, 3900) } }];
